"""Keep the stock *_contexts entries that use types generated by cil2te.py and
whose key is not already labelled by our own policy.
  ctx.py stock_ctx our_ctx stock_vendor.te out  (all types cil2te.py knows, new or AOSP)"""
import re, sys
stock, ours, te, out = sys.argv[1:5]
import os
new = set(open(os.path.join(os.path.dirname(te),'.known_types')).read().split())
def entries(p):
    r=[]
    for l in open(p):
        s=l.strip()
        if not s or s.startswith('#'): continue
        r.append(s)
    return r
def key(s): return s.split()[0] if not s.startswith('/') else ' '.join(s.split()[:-1])
ourkeys={key(s) for s in entries(ours)} if ours!='-' else set()
keep=[];skip=0
for s in entries(stock):
    ctx=re.search(r'u:object_r:([^:\s]+):s0', s)
    if not ctx: continue
    if ctx.group(1) in new and key(s) not in ourkeys: keep.append(s)
    else: skip+=1
open(out,'w').write('# Generated from the stock RMX3511 vendor policy by tools/selinux/ctx.py.\n'+'\n'.join(keep)+'\n')
print(out, 'kept', len(keep), 'skipped', skip)
